import React, { useState } from 'react';
import { View, Text, TextInput, TouchableOpacity, FlatList, Image, StyleSheet, Modal, Dimensions } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { doc, updateDoc, arrayRemove } from 'firebase/firestore';
import { db } from '../config';
import { BRAND } from './theme';

const W = Dimensions.get('window').width / 3 - 2;
const thumb = (p: any) => (p?.mediaType === 'video' && p?.mediaUrl ? p.mediaUrl.replace(/\.[^/.]+$/, '.jpg') : p?.mediaUrl);

export function SavedView({ myUid, me, posts, onBack, onOpenReel, c }: any) {
  const [filter, setFilter] = useState<'All' | 'Collections' | 'Reels' | 'Posts' | 'Audio'>('All');
    const [searching, setSearching] = useState(false);
      const [q, setQ] = useState('');
        const [showNew, setShowNew] = useState(false);
          const [colName, setColName] = useState('');
            const [activeCol, setActiveCol] = useState<any>(null);
              const [manage, setManage] = useState(false);
                const [picked, setPicked] = useState<string[]>([]);
                  const [pickColModal, setPickColModal] = useState(false);

                    const savedIds: string[] = me?.savedPosts || [];
                      const allSaved = posts.filter((p: any) => savedIds.includes(p.id) || (p.savedBy || []).includes(myUid));
                        const collections: any[] = me?.collections || [];

                          let shown = activeCol ? allSaved.filter((p: any) => (activeCol.postIds || []).includes(p.id)) : allSaved;
                            if (filter === 'Reels' || filter === 'Audio') shown = shown.filter((p: any) => p.mediaType === 'video');
                              if (filter === 'Posts') shown = shown.filter((p: any) => p.mediaType !== 'video');
                                if (q.trim()) shown = shown.filter((p: any) => (p.caption || '').toLowerCase().includes(q.toLowerCase()) || (p.username || '').toLowerCase().includes(q.toLowerCase()));

                                  const createCollection = async () => {
                                      const name = colName.trim();
                                          if (!name || !myUid) return;
                                              const next = [...collections, { id: `col_${Date.now()}`, name, postIds: picked }];
                                                  await updateDoc(doc(db, 'users', myUid), { collections: next });
                                                      setColName(''); setPicked([]); setManage(false); setShowNew(false);
                                                        };

                                                          const addToCol = async (colId: string) => {
                                                              const next = collections.map((col) => col.id === colId ? { ...col, postIds: Array.from(new Set([...(col.postIds || []), ...picked])) } : col);
                                                                  await updateDoc(doc(db, 'users', myUid), { collections: next });
                                                                      setPickColModal(false); setManage(false); setPicked([]);
                                                                        };

                                                                          const unsavePicked = async () => {
                                                                              if (!picked.length) return;
                                                                                  await updateDoc(doc(db, 'users', myUid), { savedPosts: arrayRemove(...picked) });
                                                                                      for (const id of picked) await updateDoc(doc(db, 'posts', id), { savedBy: arrayRemove(myUid) }).catch(() => {});
                                                                                          setManage(false); setPicked([]);
                                                                                            };

                                                                                              return (
                                                                                                  <View style={{ flex: 1, backgroundColor: c.background }}>
                                                                                                        <View style={s.hdr}>
                                                                                                                <TouchableOpacity onPress={activeCol ? () => setActiveCol(null) : onBack}><Ionicons name="arrow-back" size={24} color={c.text} /></TouchableOpacity>
                                                                                                                        <Text style={[s.title, { color: c.text }]}>{activeCol ? activeCol.name : 'Saved'}</Text>
                                                                                                                                <View style={{ flexDirection: 'row', gap: 14 }}>
                                                                                                                                          <TouchableOpacity onPress={() => setSearching((p) => !p)}><Ionicons name="search" size={22} color={c.text} /></TouchableOpacity>
                                                                                                                                                    <TouchableOpacity onPress={() => setShowNew(true)}><Ionicons name="add" size={26} color={c.text} /></TouchableOpacity>
                                                                                                                                                            </View>
                                                                                                                                                                  </View>

                                                                                                                                                                        {searching && (
                                                                                                                                                                                <View style={[s.sBox, { backgroundColor: c.input }]}>
                                                                                                                                                                                          <Ionicons name="search" size={17} color={c.muted} />
                                                                                                                                                                                                    <TextInput value={q} onChangeText={setQ} placeholder="Search saved reels or collections..." placeholderTextColor={c.muted} style={{ flex: 1, color: c.text, marginLeft: 8 }} />
                                                                                                                                                                                                              {!!q && <TouchableOpacity onPress={() => setQ('')}><Ionicons name="close-circle" size={17} color={c.muted} /></TouchableOpacity>}
                                                                                                                                                                                                                      </View>
                                                                                                                                                                                                                            )}

                                                                                                                                                                                                                                  {!activeCol && (
                                                                                                                                                                                                                                          <FlatList
                                                                                                                                                                                                                                                    horizontal showsHorizontalScrollIndicator={false} style={{ maxHeight: 46 }}
                                                                                                                                                                                                                                                              contentContainerStyle={{ paddingHorizontal: 14, gap: 8, alignItems: 'center' }}
                                                                                                                                                                                                                                                                        data={['All', 'Collections', 'Reels', 'Posts', 'Audio'] as const}
                                                                                                                                                                                                                                                                                  keyExtractor={(i) => i}
                                                                                                                                                                                                                                                                                            renderItem={({ item }) => (
                                                                                                                                                                                                                                                                                                        <TouchableOpacity onPress={() => setFilter(item)} style={[s.chip, { backgroundColor: filter === item ? '#E5E7EB' : c.background, borderColor: c.border }]}>
                                                                                                                                                                                                                                                                                                                      <Text style={{ fontSize: 13, fontWeight: '600', color: c.text }}>{item}</Text>
                                                                                                                                                                                                                                                                                                                                  </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                            )}
                                                                                                                                                                                                                                                                                                                                                    />
                                                                                                                                                                                                                                                                                                                                                          )}

                                                                                                                                                                                                                                                                                                                                                                {!activeCol && (filter === 'All' || filter === 'Collections') && collections.length > 0 && (
                                                                                                                                                                                                                                                                                                                                                                        <View style={{ paddingHorizontal: 14, paddingTop: 10 }}>
                                                                                                                                                                                                                                                                                                                                                                                  <Text style={{ fontSize: 15, fontWeight: '700', color: c.text, marginBottom: 8 }}>Collections</Text>
                                                                                                                                                                                                                                                                                                                                                                                            <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 12 }}>
                                                                                                                                                                                                                                                                                                                                                                                                        {collections.filter((col) => !q || col.name.toLowerCase().includes(q.toLowerCase())).map((col) => {
                                                                                                                                                                                                                                                                                                                                                                                                                      const first = allSaved.find((p: any) => (col.postIds || []).includes(p.id));
                                                                                                                                                                                                                                                                                                                                                                                                                                    return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                    <TouchableOpacity key={col.id} style={{ flexDirection: 'row', alignItems: 'center', gap: 10, width: '47%' }} onPress={() => setActiveCol(col)}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {first ? <Image source={{ uri: thumb(first) }} style={s.colThumb} /> : <View style={[s.colThumb, { backgroundColor: c.input, alignItems: 'center', justifyContent: 'center' }]}><Ionicons name="bookmark" size={20} color={c.muted} /></View>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <View style={{ flex: 1 }}><Text style={{ fontWeight: '700', color: c.text }} numberOfLines={1}>{col.name}</Text><Text style={{ fontSize: 11, color: c.muted }}>Private · {(col.postIds || []).length}</Text></View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  })}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {filter !== 'Collections' && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <View style={s.secRow}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Text style={{ fontSize: 15, fontWeight: '700', color: c.text }}>Reels and posts</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <TouchableOpacity onPress={() => { setManage((p) => !p); setPicked([]); }}><Text style={{ color: '#3B82F6', fontWeight: '600' }}>{manage ? 'Done' : 'Manage'}</Text></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <FlatList
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          data={shown} numColumns={3} keyExtractor={(i) => i.id}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ListEmptyComponent={<Text style={{ textAlign: 'center', color: c.muted, marginTop: 40 }}>No saved items yet</Text>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  renderItem={({ item }) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const isSel = picked.includes(item.id);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <TouchableOpacity style={s.tile} onPress={() => manage ? setPicked((p) => p.includes(item.id) ? p.filter((x) => x !== item.id) : [...p, item.id]) : onOpenReel(item)}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Image source={{ uri: thumb(item) }} style={s.tileImg} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {item.mediaType === 'video' && <Ionicons name="play-circle" size={20} color="#fff" style={s.playIco} />}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {manage && <Ionicons name={isSel ? 'checkbox' : 'square-outline'} size={22} color={isSel ? '#3B82F6' : '#fff'} style={s.chk} />}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {manage && picked.length > 0 && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <View style={[s.mBar, { backgroundColor: c.background, borderTopColor: c.border }]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <TouchableOpacity onPress={() => setPickColModal(true)}><Text style={{ fontWeight: '700', color: '#3B82F6' }}>Add to collection ({picked.length})</Text></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <TouchableOpacity onPress={unsavePicked}><Text style={{ fontWeight: '700', color: '#EF4444' }}>Unsave</Text></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Modal visible={showNew} transparent animationType="slide" onRequestClose={() => setShowNew(false)}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <View style={s.mBg}><View style={[s.sheet, { backgroundColor: c.background }]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <View style={s.sHdr}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <TouchableOpacity onPress={() => setShowNew(false)}><Text style={{ color: c.text, fontSize: 15 }}>Cancel</Text></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Text style={{ fontWeight: '700', fontSize: 16, color: c.text }}>New collection</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <TouchableOpacity onPress={createCollection}><Text style={{ color: colName.trim() ? '#3B82F6' : c.muted, fontWeight: '700', fontSize: 15 }}>Save</Text></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <TextInput value={colName} onChangeText={setColName} placeholder="Collection name" placeholderTextColor={c.muted} style={[s.colInp, { borderColor: c.text, color: c.text }]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </View></View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </Modal>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Modal visible={pickColModal} transparent animationType="fade" onRequestClose={() => setPickColModal(false)}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <TouchableOpacity style={s.mBg} activeOpacity={1} onPress={() => setPickColModal(false)}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <View style={[s.sheet, { backgroundColor: c.background }]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <Text style={{ fontWeight: '700', fontSize: 16, color: c.text, marginBottom: 10 }}>Choose collection</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {collections.map((col) => <TouchableOpacity key={col.id} style={{ paddingVertical: 12 }} onPress={() => addToCol(col.id)}><Text style={{ color: c.text, fontSize: 15 }}>{col.name}</Text></TouchableOpacity>)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <TouchableOpacity style={{ paddingVertical: 12 }} onPress={() => { setPickColModal(false); setShowNew(true); }}><Text style={{ color: BRAND, fontWeight: '700' }}>+ Create new collection</Text></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </Modal>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const s = StyleSheet.create({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                hdr: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingTop: 48, paddingBottom: 10, paddingHorizontal: 16 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  title: { fontSize: 19, fontWeight: '700' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    sBox: { flexDirection: 'row', alignItems: 'center', marginHorizontal: 14, marginBottom: 8, paddingHorizontal: 12, paddingVertical: 8, borderRadius: 12 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      chip: { paddingHorizontal: 14, paddingVertical: 6, borderRadius: 18, borderWidth: 1 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        colThumb: { width: 56, height: 56, borderRadius: 10 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          secRow: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', paddingHorizontal: 14, paddingVertical: 12 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            tile: { width: W, height: W * 1.25, margin: 1 }, tileImg: { width: '100%', height: '100%' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              playIco: { position: 'absolute', top: 6, right: 6 }, chk: { position: 'absolute', bottom: 6, right: 6 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                mBar: { flexDirection: 'row', justifyContent: 'space-around', paddingVertical: 14, borderTopWidth: 0.5 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  mBg: { flex: 1, backgroundColor: 'rgba(0,0,0,0.45)', justifyContent: 'flex-end' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    sheet: { borderTopLeftRadius: 20, borderTopRightRadius: 20, padding: 18, paddingBottom: 32 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      sHdr: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        colInp: { borderWidth: 1.5, borderRadius: 12, paddingHorizontal: 14, paddingVertical: 12, fontSize: 15 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        